-- Name: settings_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.settings_settings (
    id bigint NOT NULL,
    bot_token character varying(80) NOT NULL,
    prefix character varying(10) NOT NULL,
    collectible_name text NOT NULL,
    plural_collectible_name text NOT NULL,
    bot_name text NOT NULL,
    cricstar_slash_name text NOT NULL,
    favorited_collectible_emoji character varying(3) NOT NULL,
    max_favorites integer NOT NULL,
    max_attack_bonus integer NOT NULL,
    max_health_bonus integer NOT NULL,
    show_rarity boolean NOT NULL,
    catch_button_label character varying(80) NOT NULL,
    spawn_chance_min integer NOT NULL,
    spawn_chance_max integer NOT NULL,
    spawn_manager text NOT NULL,
    about_description text NOT NULL,
    repository character varying(200) NOT NULL,
    discord_invite character varying(200) NOT NULL,
    terms_of_service character varying(200) NOT NULL,
    privacy_policy character varying(200) NOT NULL,
    admin_channel_ids text NOT NULL,
    webhook_logging character varying(200),
    team_owners boolean NOT NULL,
    coowners text,
    prometheus_enabled boolean NOT NULL,
    prometheus_host inet NOT NULL,
    prometheus_port integer NOT NULL,
    client_id bigint,
    client_secret text,
    sentry_dsn character varying(200),
    sentry_env character varying(64) NOT NULL,
    currency_name character varying(32),
    currency_plural_name character varying(32),
    currency_symbol character varying(4),
    currency_symbol_before boolean NOT NULL,
    site_base_url character varying(200) NOT NULL,
    CONSTRAINT oauth_params_null_together CHECK (((((client_id IS NULL) OR (client_id = 0)) AND ((client_secret IS NULL) OR (client_secret = ''::text))) OR ((client_id IS NOT NULL) AND (client_secret IS NOT NULL)))),
    CONSTRAINT settings_settings_client_id_check CHECK ((client_id >= 0)),
    CONSTRAINT settings_settings_max_attack_bonus_check CHECK ((max_attack_bonus >= 0)),
    CONSTRAINT settings_settings_max_favorites_check CHECK ((max_favorites >= 0)),
    CONSTRAINT settings_settings_max_health_bonus_check CHECK ((max_health_bonus >= 0)),
    CONSTRAINT settings_settings_prometheus_port_check CHECK ((prometheus_port >= 0)),
    CONSTRAINT settings_settings_spawn_chance_max_check CHECK ((spawn_chance_max >= 0)),
    CONSTRAINT settings_settings_spawn_chance_min_check CHECK ((spawn_chance_min >= 0)),
    CONSTRAINT spawn_chance_min_lt_max CHECK ((spawn_chance_min <= spawn_chance_max))
);


